import { validate } from "../services/customer.ts";
import { checkoutOrder } from "../services/checkout.ts";
import type { OrderInput, SavedOrder } from "../types.ts";

// HTTP route equivalent: POST /orders.
export function submitOrder(input: OrderInput): SavedOrder {
  validate(input.customer);
  return checkoutOrder(input);
}

import { calculateSubtotal } from "./pricing.ts";
import { applyDiscount } from "./discount.ts";
import { calculateShipping } from "./shipping.ts";
import { reserveStock } from "./inventory.ts";
import { saveOrder } from "../storage/orders.ts";
import type { OrderInput, SavedOrder } from "../types.ts";

export function checkoutOrder(input: OrderInput): SavedOrder {
  const subtotal = calculateSubtotal(input.items);
  const discount = applyDiscount(subtotal, input.coupon);
  const shipping = calculateShipping(input.items, input.customer.region);
  reserveStock(input.items);
  return saveOrder(input.customer.id, {
    subtotal, discount, shipping, total: subtotal - discount + shipping,
  });
}

import type { Customer } from "../types.ts";

// Same symbol name as inventory.validate; the import target should disambiguate it.
export function validate(customer: Customer): void {
  if (!customer.id.trim()) throw new Error("Customer id is required");
}

export function applyDiscount(subtotal: number, coupon?: string): number {
  return coupon === "SAVE10" ? Math.floor(subtotal * 0.1) : 0;
}

import { calculateShipping as shippingCost } from "./shipping.ts";
import { calculateSubtotal } from "./pricing.ts";
import { applyDiscount } from "./discount.ts";
import type { OrderInput, Quote } from "../types.ts";

// Quote calculation shares shipping logic through a named import alias.
export function estimateOrder(input: OrderInput): Quote {
  const subtotal = calculateSubtotal(input.items);
  const discount = applyDiscount(subtotal, input.coupon);
  const shipping = shippingCost(input.items, input.customer.region);
  return { subtotal, discount, shipping, total: subtotal - discount + shipping };
}

import type { CartItem } from "../types.ts";

// Same symbol name as customer.validate, with different callers.
export function validate(items: CartItem[]): void {
  if (!items.length || items.some(item => item.quantity < 1)) {
    throw new Error("Cart must contain positive quantities");
  }
}

export function reserveStock(items: CartItem[]): number {
  validate(items);
  return items.reduce((quantity, item) => quantity + item.quantity, 0);
}

import type { CartItem } from "../types.ts";

export function calculateSubtotal(items: CartItem[]): number {
  return items.reduce((sum, item) => sum + item.quantity * item.unitPrice, 0);
}

import type { CartItem, Customer } from "../types.ts";

// All money values are integer cents. Free shipping starts at a 10,000-cent subtotal.
export function calculateShipping(items: CartItem[], region: Customer["region"]): number {
  const subtotal = items.reduce((sum, item) => sum + item.unitPrice * item.quantity, 0);
  if (subtotal >= 10000 && region === "local") return 0;
  const weight = items.reduce((sum, item) => sum + item.weight * item.quantity, 0);
  return (region === "remote" ? 1200 : 500) + Math.max(0, Math.ceil(weight) - 1) * 200;
}

import type { Quote, SavedOrder } from "../types.ts";

// Deliberately deterministic, in-memory example; no database or payment side effect.
export function saveOrder(customerId: string, quote: Quote): SavedOrder {
  return { id: `demo-${customerId}`, customerId, status: "confirmed", ...quote };
}

export interface CartItem { sku: string; quantity: number; unitPrice: number; weight: number }
export interface Customer { id: string; region: "local" | "remote" }
export interface OrderInput { customer: Customer; items: CartItem[]; coupon?: string }
export interface Quote { subtotal: number; discount: number; shipping: number; total: number }
export interface SavedOrder extends Quote { id: string; customerId: string; status: "confirmed" }

import assert from "node:assert/strict";
import { submitOrder } from "./routes/order.ts";
import { estimateOrder } from "./services/estimate.ts";
import type { OrderInput } from "./types.ts";

const input: OrderInput = {
  customer: { id: "buyer-01", region: "local" },
  items: [{ sku: "BOOK", quantity: 2, unitPrice: 3000, weight: 0.5 }],
  coupon: "SAVE10",
};
const cases = [
  { name: "local-discount", input, expected: 5900 },
  { name: "remote-shipping", input: { ...input, customer: { id: "buyer-02", region: "remote" as const } }, expected: 6600 },
  { name: "free-shipping", input: { ...input, items: [{ sku: "DESK", quantity: 1, unitPrice: 12000, weight: 3 }] }, expected: 10800 },
];
const results = cases.map(test => {
  const quote = estimateOrder(test.input);
  const order = submitOrder(test.input);
  assert.equal(order.total, test.expected);
  assert.equal(quote.total, order.total);
  return { name: test.name, passed: true, total: order.total, quoteMatchesCheckout: true };
});
assert.throws(() => submitOrder({ ...input, customer: { id: "", region: "local" } }), /Customer/);
assert.throws(() => submitOrder({ ...input, items: [] }), /positive quantities/);
console.log(JSON.stringify({ status: "passed", cases: results, invalidCustomerRejected: true, emptyCartRejected: true }, null, 2));
